input.command:
c(){ find "$@" 2>/dev/null | wc -l; }
echo src_py $(c src -name '*.py' -not -path '*/__pycache__/*')
echo commands $(c src/superclaude/commands -maxdepth 2 -name '*.md' -not -name README.md)
echo agents $(c src/superclaude/agents -maxdepth 1 -name '*.md' -not -name README.md)
echo skills $(find src/superclaude/skills -maxdepth 2 -name SKILL.md | wc -l)
echo modes $(c src/superclaude/modes -name '*.md')
echo core $(c src/superclaude/core -maxdepth 1 -name '*.md')
echo docs_md $(c docs -name '*.md')
echo plugins_files $(c plugins -type f)
echo scripts_files $(c scripts -type f)
echo VERSION $(cat VERSION); grep -m1 '"version"' package.json
echo --- cli; ls src/superclaude/cli | grep -v __pycache__ | tr '\n' ' '; echo
echo --- core; ls src/superclaude/core | tr '\n' ' '; echo
echo --- modes; ls src/superclaude/modes | tr '\n' ' '; echo
echo --- scripts; ls scripts | tr '\n' ' '; echo
echo --- root cfg; ls *.toml *.json *.yaml *.yml .pre-commit-config.yaml .github/workflows 2>/dev/null | tr '\n' ' '; echo
echo --- make; grep -E '^[a-zA-Z_-]+:' Makefile | cut -d: -f1 | tr '\n' ' '; echo
echo --- cli main; ls src/superclaude/cli/main.py src/superclaude/cli/ic.py
